// Gear you wield or wear: weapons, armor, shields and fundamental runes.

// Weapon fundamental runes (GM Core): a potency rune grants an item bonus to attack rolls and lets
// the weapon hold property runes; a striking rune adds extra weapon damage dice (Striking +1,
// Greater +2, Major +3). Both default to none on a freshly added weapon, and `value`, `bonus` and
// `extraDice` drive the attack and damage maths while the rest of each entry is the rune's own
// stat block, shown in the runes browser.
export const POTENCY_RUNES = [
  { value: 'none', label: 'None', bonus: 0 },
  { value: '+1', label: '+1 Potency', name: 'Weapon Potency (+1)', bonus: 1, level: 2, price: '35 gp', book: 'gm-core', traits: 'Magical', usage: 'etched onto a weapon', desc: 'Magical enhancements make this weapon strike true. Attack rolls with this weapon gain a +1 item bonus, and the weapon can be etched with one property rune.\nYou can upgrade the weapon potency rune already etched on a weapon to a stronger version, increasing the values of the existing rune to those of the new rune. The Price of the upgrade is the difference between the two runes’ prices.' },
  { value: '+2', label: '+2 Potency', name: 'Weapon Potency (+2)', bonus: 2, level: 10, price: '935 gp', book: 'gm-core', traits: 'Magical', usage: 'etched onto a weapon', desc: 'Magical enhancements make this weapon strike true. Attack rolls with this weapon gain a +1 item bonus, and the weapon can be etched with one property rune.\nYou can upgrade the weapon potency rune already etched on a weapon to a stronger version, increasing the values of the existing rune to those of the new rune. The Price of the upgrade is the difference between the two runes’ prices.\nWeapon Potency (+2) - The item bonus to attack rolls is +2, and the weapon can be etched with two property runes.' },
  { value: '+3', label: '+3 Potency', name: 'Weapon Potency (+3)', bonus: 3, level: 16, price: '8,935 gp', book: 'gm-core', traits: 'Magical', usage: 'etched onto a weapon', desc: 'Magical enhancements make this weapon strike true. Attack rolls with this weapon gain a +1 item bonus, and the weapon can be etched with one property rune.\nYou can upgrade the weapon potency rune already etched on a weapon to a stronger version, increasing the values of the existing rune to those of the new rune. The Price of the upgrade is the difference between the two runes’ prices.\nWeapon Potency (+3) - The item bonus to attack rolls is +3, and the weapon can be etched with three property runes.' },
];

